mapper.select:
SELECT c.*, cl.name as collegeName FROM course c LEFT JOIN college cl ON c.college_id = cl.id AND cl.deleted = 0 WHERE c.deleted = 0
AND c.course_no LIKE CONCAT('%', #{params.courseNo}, '%')
AND c.name LIKE CONCAT('%', #{params.name}, '%')
AND c.category = #{params.category}
AND c.college_id = #{params.collegeId}
ORDER BY c.create_time DESC
